{
    GrimUV *row = grim_font2_uv_u;
    for (int y = 0; y < 16; ++y) {
        float row_v = (float)y * 0.0625f;
        GrimUV *entry = row;
        row += 16;
        for (int x = 0; x < 16; ++x, ++entry) {
            entry->u = (float)x * 0.0625f;
            entry->v = row_v;
        }
    }
}

